using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
namespace B1InputChannel002 {
[InitializeOnLoad] public static class NeutralEntry {
 const string Armed="B1.Input002.Armed";static DateTime deadline;static bool stopRequested{get{return SessionState.GetBool(Armed+".Stopping",false);}set{SessionState.SetBool(Armed+".Stopping",value);}}
 [Serializable] class Request{public string unity,project,output,company,product;public Source[] sources;}
 [Serializable] class Source{public string path,sha256;}
 [Serializable] class Terminal{public string status,unity,project,error,runIdentity,company,product,persistentDataPath;public bool isBatchMode,playing,compiling,updating,cleanupVerified;public int patches,loops,virtualKeys;}
 [Serializable] class ExitInvocation{public string status,utc,runIdentity,company,product,persistentDataPath;public int pid;public bool isBatchMode,playing,compiling,updating;}
 static Request request;
 static string Root{get{return Path.GetFullPath(Path.GetDirectoryName(Application.dataPath));}}
 static NeutralEntry(){AssemblyReloadEvents.beforeAssemblyReload+=Cleanup;EditorApplication.playModeStateChanged+=Mode;EditorApplication.update+=Pump;}
 static Request Load(){var r=JsonUtility.FromJson<Request>(File.ReadAllText(Path.Combine(Root,"input002-request.json")));if(r.unity!="2022.3.62f2"||Application.unityVersion!=r.unity||Path.GetFullPath(r.project)!=Root||Path.GetFullPath(r.output)!=Path.Combine(Directory.GetParent(Root).FullName,"Evidence")||r.company!="B1JudgeNeutral"||r.product!="TypedKeyCode002NeutralAttempt2")throw new Exception("Neutral request identity mismatch");foreach(var s in r.sources){var file=Path.GetFullPath(Path.Combine(Root,s.path));if(!file.StartsWith(Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||TypedKeyChannel.SHA(File.ReadAllBytes(file))!=s.sha256)throw new Exception("Pre-run immutable fixture hash mismatch");}return r;}
 // Explicit executeMethod entry only. Merely importing this file cannot start a run.
 public static void Start(){if(SessionState.GetBool(Armed,false)||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)throw new Exception("Neutral editor not idle");request=Load();if(!Application.isBatchMode)throw new Exception("Neutral first run requires batchmode");SessionState.SetString(Armed+".RunIdentity",Guid.NewGuid().ToString("N"));if(Directory.Exists(request.output)&&Directory.EnumerateFileSystemEntries(request.output).Any())throw new Exception("Refuse to overwrite previous calibration evidence");Directory.CreateDirectory(request.output);PlayerSettings.companyName=request.company;PlayerSettings.productName=request.product;deadline=DateTime.UtcNow.AddSeconds(210);stopRequested=false;SessionState.SetBool(Armed,true);EditorApplication.isPlaying=true;}
 static void Mode(PlayModeStateChange state){if(!SessionState.GetBool(Armed,false))return;try{if(state==PlayModeStateChange.EnteredPlayMode){request=Load();NeutralRun.RunIdentity=SessionState.GetString(Armed+".RunIdentity","");NeutralRun.Project=request.project;NeutralRun.Output=request.output;NeutralRun.Done=false;NeutralRun.Error=null;new GameObject("B1Input002NeutralDriver").AddComponent<NeutralRun>();deadline=DateTime.UtcNow.AddSeconds(210);}if(state==PlayModeStateChange.ExitingPlayMode){stopRequested=true;Cleanup();}}catch(Exception e){Block(e);}}
 static void Cleanup(){TypedKeyChannel.Cleanup();}
 static void Block(Exception e){request=request??Load();Directory.CreateDirectory(request.output);File.WriteAllText(Path.Combine(request.output,"infrastructure-error.txt"),e.ToString());Cleanup();EditorApplication.isPlaying=false;stopRequested=true;}
 static void Pump(){if(!SessionState.GetBool(Armed,false))return;try{request=request??Load();if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(EditorApplication.isPlaying){if(NeutralRun.Done&&!stopRequested){stopRequested=true;EditorApplication.isPlaying=false;}else if(deadline!=default(DateTime)&&DateTime.UtcNow>deadline)Block(new TimeoutException("Neutral editor pump timeout"));else EditorApplication.QueuePlayerLoopUpdate();return;}if(EditorApplication.isPlayingOrWillChangePlaymode||!stopRequested)return;request=Load();Cleanup();var report=Path.Combine(request.output,"run-completed.json");bool clean=TypedKeyChannel.PatchCount()==0&&TypedKeyChannel.LoopCount()==0&&TypedKeyChannel.VirtualCount()==0;var t=new Terminal{status=clean&&File.Exists(report)&&!File.Exists(Path.Combine(request.output,"infrastructure-error.txt"))?"idle_pending_independent_review":"blocked",unity=Application.unityVersion,project=Root,company=Application.companyName,product=Application.productName,persistentDataPath=Application.persistentDataPath,runIdentity=SessionState.GetString(Armed+".RunIdentity",""),isBatchMode=Application.isBatchMode,playing=false,compiling=EditorApplication.isCompiling,updating=EditorApplication.isUpdating,cleanupVerified=clean,patches=TypedKeyChannel.PatchCount(),loops=TypedKeyChannel.LoopCount(),virtualKeys=TypedKeyChannel.VirtualCount()};File.WriteAllText(Path.Combine(request.output,"terminal-idle.json"),JsonUtility.ToJson(t,true));SessionState.SetBool(Armed,false);if(Application.isBatchMode){var exit=new ExitInvocation{status="normal_exit_invoked_not_observed_complete",utc=DateTime.UtcNow.ToString("o"),runIdentity=t.runIdentity,company=Application.companyName,product=Application.productName,persistentDataPath=Application.persistentDataPath,pid=System.Diagnostics.Process.GetCurrentProcess().Id,isBatchMode=true,playing=EditorApplication.isPlaying,compiling=EditorApplication.isCompiling,updating=EditorApplication.isUpdating};File.WriteAllText(Path.Combine(request.output,"exit-invocation.json"),JsonUtility.ToJson(exit,true));EditorApplication.Exit(0);}}catch(Exception e){Debug.LogException(e);try{Block(e);}catch(Exception nested){Debug.LogException(nested);SessionState.SetBool(Armed,false);}}}
}
}
